import http from 'k6/http';
import { check, sleep } from 'k6';

const baseUrl = __ENV.K6_BASE_URL || 'http://localhost:3000';
const targetFramework = __ENV.TARGET_FRAMEWORK || 'express';
const warmupSeconds = Number(__ENV.WARMUP_SECONDS || 120);
const rampUpSeconds = Number(__ENV.RAMP_UP_SECONDS || 30);
const sustainSeconds = Number(__ENV.SUSTAIN_SECONDS || 120);
const concurrentUsers = Number(__ENV.CONCURRENT_USERS || 100);

export const options = {
  scenarios: {
    main_load: {
      executor: 'ramping-vus',
      startVUs: 0,
      stages: [
        { duration: `${rampUpSeconds}s`, target: concurrentUsers },
        { duration: `${sustainSeconds}s`, target: concurrentUsers },
        { duration: '10s', target: 0 },
      ],
      gracefulRampDown: '10s',
      exec: 'mainScenario',
    },
  },
  thresholds: {
    http_req_failed: ['rate<0.05'],
    http_req_duration: ['p(95)<5000'],
  },
  summaryTrendStats: ['min', 'avg', 'med', 'p(90)', 'p(95)', 'p(99)'],
};

export function setup() {
  const endAt = Date.now() + warmupSeconds * 1000;
  while (Date.now() < endAt) {
    http.get(`${baseUrl}/health`);
    sleep(1);
  }
  return { baseUrl, targetFramework };
}

function randomInt(min, max) {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

function pickPage() {
  return randomInt(1, 2500);
}

export function mainScenario(data) {
  const scenarioRoll = Math.random();

  if (scenarioRoll < 0.68) {
    const url = `${data.baseUrl}/api/products?page=${pickPage()}&perPage=20&search=Product&status=active&minPrice=10000&maxPrice=7500000`;
    const response = http.get(url, {
      tags: { scenario: 'list', framework: data.targetFramework },
    });
    check(response, { 'list status 200': r => r.status === 200 });
    return;
  }

  if (scenarioRoll < 0.86) {
    const id = randomInt(1, 100000);
    const response = http.get(`${data.baseUrl}/api/products/${id}`, {
      tags: { scenario: 'show', framework: data.targetFramework },
    });
    check(response, { 'show status 200 or 404': r => r.status === 200 || r.status === 404 });
    return;
  }

  if (scenarioRoll < 0.92) {
    const payload = JSON.stringify({
      category_id: randomInt(1, 50),
      brand_id: randomInt(1, 100),
      sku: `SKU-K6-${__VU}-${__ITER}-${Date.now()}`,
      name: `K6 Product ${__VU}-${__ITER}`,
      description: 'Generated by k6 for CRUD benchmark',
      price: Number((Math.random() * 9000000 + 10000).toFixed(2)),
      status: 'active',
      stock: randomInt(1, 1000),
      reserved: randomInt(0, 50),
      warehouse_location: 'WH-1',
    });

    const response = http.post(`${data.baseUrl}/api/products`, payload, {
      headers: { 'Content-Type': 'application/json' },
      tags: { scenario: 'create', framework: data.targetFramework },
    });
    check(response, { 'create status 201': r => r.status === 201 });
    return;
  }

  if (scenarioRoll < 0.97) {
    const id = randomInt(1, 100000);
    const payload = JSON.stringify({
      name: `Updated Product ${__VU}-${__ITER}`,
      description: 'Updated during benchmark',
      price: Number((Math.random() * 9000000 + 10000).toFixed(2)),
      status: 'active',
      stock: randomInt(1, 1000),
      reserved: randomInt(0, 50),
    });

    const response = http.put(`${data.baseUrl}/api/products/${id}`, payload, {
      headers: { 'Content-Type': 'application/json' },
      tags: { scenario: 'update', framework: data.targetFramework },
    });
    check(response, { 'update status 200/404': r => r.status === 200 || r.status === 404 });
    return;
  }

  const id = randomInt(1, 100000);
  const response = http.del(`${data.baseUrl}/api/products/${id}`, null, {
    tags: { scenario: 'delete', framework: data.targetFramework },
  });
  check(response, { 'delete status 200/404': r => r.status === 200 || r.status === 404 });
}
